values (
  $sujet$arabe$sujet$,
  2024,
  $sujet$normale$sujet$,
  $sujet$Marrakech-Safi$sujet$,
  $sujet$الشعب العلمية والتقنية (التجريبية، الرياضية، الاقتصاد والتدبير، العلوم والتكنولوجيات، الفنون التطبيقية) - خاص بالمترشحين الممدرسين$sujet$,
